formulas.expression:
IF(
ISBLANK({!Resume_ACH_Date}),
"ACH Status: Stop - " + TEXT(MONTH({!StopACHDate}))+"/"+TEXT(DAY({!StopACHDate}))+"/"+TEXT(YEAR({!StopACHDate})) + {!formulaLineBreak},
"ACH Status: Stop - " + TEXT(MONTH({!StopACHDate}))+"/"+TEXT(DAY({!StopACHDate}))+"/"+TEXT(YEAR({!StopACHDate})) + " Resume ACH: " + TEXT(MONTH({!Resume_ACH_Date}))+"/"+TEXT(DAY({!Resume_ACH_Date}))+"/"+TEXT(YEAR({!Resume_ACH_Date})) + {!formulaLineBreak}
)
